@Test
public void testWriting() throws TripleHandlerException {
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    jsonWriter = new JSONWriter(baos);
    final URI documentURI = new URIImpl("http://fake/uri");
    jsonWriter.startDocument(documentURI);
    jsonWriter.receiveTriple(new BNodeImpl("bn1"), new URIImpl("http://pred/1"), new URIImpl("http://value/1"), new URIImpl("http://graph/1"), null);
    jsonWriter.receiveTriple(new URIImpl("http://sub/2"), new URIImpl("http://pred/2"), new LiteralImpl("language literal", "en"), new URIImpl("http://graph/2"), null);
    jsonWriter.receiveTriple(new URIImpl("http://sub/3"), new URIImpl("http://pred/3"), new LiteralImpl("123", new URIImpl("http://datatype")), null, null);
    jsonWriter.endDocument(documentURI);
    jsonWriter.close();
    final String expected = "{ " + "\"quads\" : " + "[" + "[" + "{ \"type\" : \"bnode\", \"value\" : \"bn1\"}, " + "\"http://pred/1\", " + "{ \"type\" : \"uri\", \"value\" : \"http://value/1\"}, " + "\"http://graph/1\"" + "], " + "[" + "{ \"type\" : \"uri\", \"value\" : \"http://sub/2\"}, " + "\"http://pred/2\", " + "{\"type\" : \"literal\", \"value\" : \"language literal\", \"lang\" : \"en\", \"datatype\" : null}, " + "\"http://graph/2\"" + "], " + "[" + "{ \"type\" : \"uri\", \"value\" : \"http://sub/3\"}, " + "\"http://pred/3\", " + "{\"type\" : \"literal\", \"value\" : \"123\", \"lang\" : null, \"datatype\" : \"http://datatype\"}, " + "null" + "]" + "]" + "}";
    Assert.assertEquals(expected, baos.toString());
}

